def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    recent10_c = 0
    recent6_d = 0
    recent4_d = 0

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    start6 = n - 6
    if start6 < 0:
        start6 = 0
    start4 = n - 4
    if start4 < 0:
        start4 = 0

    tolerant = 0
    retaliated = 0
    unprovoked = 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
        if i >= start10 and o == 'C':
            recent10_c += 1
        if i >= start6 and o == 'D':
            recent6_d += 1
        if i >= start4 and o == 'D':
            recent4_d += 1
        if i + 1 < n:
            nm, no = history[i + 1]
            if m == 'D':
                if no == 'C':
                    tolerant += 1
                else:
                    retaliated += 1
            else:
                if no == 'D':
                    unprovoked += 1

    opp_d = n - opp_c
    my_d = n - my_c

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if opp_d == n:
        return 'D'

    if recent10_c <= 1:
        return 'D'

    if last_opp == 'D' and last_me == 'D':
        if opp_c >= opp_d and recent10_c >= 7:
            if dd_streak >= 3 or rng.random() < 0.25:
                return 'C'
        if tolerant > retaliated and recent10_c >= 6:
            if rng.random() < 0.20:
                return 'C'
        return 'D'

    if last_opp == 'D':
        return 'D'

    if last_me == 'D' and last_opp == 'C' and tolerant < 3 and opp_c >= opp_d:
        return 'C'

    if recent6_d >= 4:
        return 'D'

    if opp_d > my_d + 3 and recent10_c <= 8:
        return 'D'

    if opp_d > my_d + 1 and recent4_d >= 2:
        return 'D'

    if n == 98 and last_opp == 'C':
        if tolerant >= 1 and tolerant > retaliated and recent10_c >= 8 and opp_c >= opp_d + 1:
            return 'D'
        if opp_d == 0 and rng.random() < 0.30:
            return 'D'

    forgiving = (
        n >= 30 and
        tolerant >= 2 and
        tolerant > retaliated and
        unprovoked <= 2 and
        recent10_c >= 8 and
        recent6_d == 0 and
        opp_c >= opp_d + 2
    )

    if forgiving:
        return 'D'

    return 'C'
